# 第十期新图标（自绘、可商用、无文字）：景区闸门、令牌桶、令牌、服务器、景点、拍照点、熔断开关、降级
# 复用（自绘）：phone / guest / queue / spinner（第九期）、timer（第八期）
import os
T=dict(bg="#0B1020",surface="#111827",s2="#1F2937",border="#243045",text="#E5E7EB",text2="#9CA3AF",muted="#6B7280",primary="#22D3EE",secondary="#3B82F6",success="#22C55E",accent="#F59E0B",danger="#F87171")
OUT=os.path.join(os.path.dirname(os.path.abspath(__file__)),"assets");os.makedirs(OUT,exist_ok=True)
def svg(name,body,vb="0 0 512 512"):
    open(os.path.join(OUT,name),"w").write(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="{vb}" width="{vb.split()[2]}" height="{vb.split()[3]}">\n{body}\n</svg>\n')
# 景区大门：两根门柱 + 屋檐 + 中间闸机
svg("gate.svg",f'<path d="M40 120 L256 30 L472 120 Z" fill="{T["accent"]}"/><rect x="40" y="120" width="432" height="30" fill="{T["muted"]}"/><rect x="60" y="150" width="60" height="330" fill="{T["text2"]}"/><rect x="392" y="150" width="60" height="330" fill="{T["text2"]}"/><rect x="200" y="330" width="112" height="150" rx="12" fill="{T["s2"]}" stroke="{T["primary"]}" stroke-width="10"/><rect x="230" y="300" width="160" height="22" rx="11" fill="{T["primary"]}"/><circle cx="256" cy="370" r="14" fill="{T["success"]}"/>')
svg("gate-open.svg",f'<path d="M40 120 L256 30 L472 120 Z" fill="{T["accent"]}"/><rect x="40" y="120" width="432" height="30" fill="{T["muted"]}"/><rect x="60" y="150" width="60" height="330" fill="{T["text2"]}"/><rect x="392" y="150" width="60" height="330" fill="{T["text2"]}"/>')
# 令牌桶：桶身 + 出票口 + 桶里几张票
tok=lambda x,y,s=1:f'<g transform="translate({x} {y}) scale({s})"><rect x="0" y="0" width="90" height="56" rx="10" fill="{T["accent"]}"/><circle cx="45" cy="28" r="14" fill="{T["bg"]}"/></g>'
svg("bucket.svg",f'<path d="M80 150 H432 L392 470 H120 Z" fill="{T["s2"]}" stroke="{T["primary"]}" stroke-width="14" stroke-linejoin="round"/><path d="M80 150 C80 110 432 110 432 150" fill="none" stroke="{T["primary"]}" stroke-width="14"/>'+tok(150,360)+tok(260,380)+tok(200,300)+f'<rect x="392" y="400" width="80" height="40" rx="10" fill="{T["muted"]}"/>')
svg("bucket-empty.svg",f'<path d="M80 150 H432 L392 470 H120 Z" fill="{T["s2"]}" stroke="{T["danger"]}" stroke-width="14" stroke-linejoin="round"/><path d="M80 150 C80 110 432 110 432 150" fill="none" stroke="{T["danger"]}" stroke-width="14"/><rect x="392" y="400" width="80" height="40" rx="10" fill="{T["muted"]}"/>')
svg("bucket-full.svg",f'<path d="M80 150 H432 L392 470 H120 Z" fill="{T["s2"]}" stroke="{T["success"]}" stroke-width="14" stroke-linejoin="round"/><path d="M80 150 C80 110 432 110 432 150" fill="none" stroke="{T["success"]}" stroke-width="14"/>'+"".join(tok(130+(i%3)*90,380-(i//3)*60) for i in range(9))+f'<rect x="392" y="400" width="80" height="40" rx="10" fill="{T["muted"]}"/>')
svg("token.svg",tok(16,128,5.3),vb="0 0 512 512")
svg("server.svg",f'<g fill="{T["s2"]}" stroke="{T["secondary"]}" stroke-width="12">'+"".join(f'<rect x="96" y="{60+i*140}" width="320" height="110" rx="16"/>' for i in range(3))+'</g>'+"".join(f'<circle cx="150" cy="{115+i*140}" r="14" fill="{T["success"]}"/><rect x="200" y="{105+i*140}" width="170" height="20" rx="10" fill="{T["muted"]}"/>' for i in range(3)))
svg("server-down.svg",f'<g transform="rotate(8 256 256)"><g fill="{T["s2"]}" stroke="{T["danger"]}" stroke-width="12">'+"".join(f'<rect x="96" y="{60+i*140}" width="320" height="110" rx="16"/>' for i in range(3))+'</g></g>'+f'<path d="M120 120 L392 392 M392 120 L120 392" stroke="{T["danger"]}" stroke-width="30" stroke-linecap="round"/>')
svg("spot.svg",f'<path d="M60 220 L256 90 L452 220 Z" fill="{T["secondary"]}"/><rect x="110" y="220" width="292" height="40" fill="{T["muted"]}"/><rect x="140" y="260" width="40" height="200" fill="{T["text2"]}"/><rect x="332" y="260" width="40" height="200" fill="{T["text2"]}"/><rect x="100" y="460" width="312" height="30" rx="8" fill="{T["muted"]}"/>')
svg("smoke.svg",f'<g fill="{T["muted"]}" opacity="0.9"><circle cx="200" cy="300" r="90"/><circle cx="300" cy="230" r="110"/><circle cx="260" cy="120" r="80"/></g><path d="M256 330 C220 400 300 420 256 480" stroke="{T["danger"]}" stroke-width="26" fill="none" stroke-linecap="round"/>')
svg("camera.svg",f'<rect x="60" y="150" width="392" height="270" rx="40" fill="{T["s2"]}" stroke="{T["primary"]}" stroke-width="14"/><rect x="180" y="100" width="150" height="60" rx="14" fill="{T["primary"]}"/><circle cx="256" cy="285" r="85" fill="none" stroke="{T["primary"]}" stroke-width="20"/><circle cx="256" cy="285" r="36" fill="{T["primary"]}"/>')
svg("fuse.svg",f'<circle cx="120" cy="300" r="34" fill="{T["accent"]}"/><circle cx="392" cy="300" r="34" fill="{T["accent"]}"/><path d="M40 300 H86 M426 300 H472" stroke="{T["text2"]}" stroke-width="20" stroke-linecap="round"/><path d="M150 290 L340 160" stroke="{T["text"]}" stroke-width="26" stroke-linecap="round"/>')
svg("downgrade.svg",f'<g fill="{T["primary"]}"><rect x="80" y="360" width="90" height="110" rx="12"/><rect x="211" y="260" width="90" height="210" rx="12" opacity="0.5"/><rect x="342" y="160" width="90" height="310" rx="12" opacity="0.25"/></g><path d="M380 60 V140 M340 100 L380 140 L420 100" stroke="{T["accent"]}" stroke-width="26" fill="none" stroke-linecap="round" stroke-linejoin="round"/>')
print(sorted(os.listdir(OUT)))
svg("phone-busy.svg",f'<rect x="136" y="24" width="240" height="464" rx="40" fill="{T["s2"]}" stroke="{T["primary"]}" stroke-width="16"/><rect x="160" y="80" width="192" height="340" rx="12" fill="{T["surface"]}"/><path d="M216 140 H296 L296 156 L262 200 L296 244 V260 H216 V244 L250 200 L216 156 Z" fill="none" stroke="{T["accent"]}" stroke-width="12" stroke-linejoin="round"/><path d="M232 252 H280 L256 222 Z" fill="{T["accent"]}"/><rect x="190" y="300" width="132" height="16" rx="8" fill="{T["muted"]}"/><rect x="210" y="336" width="92" height="16" rx="8" fill="{T["muted"]}"/><rect x="226" y="446" width="60" height="12" rx="6" fill="{T["text2"]}"/>')
